impl Solution {
    pub fn max_k_segments_sum(nums: Vec<i64>, m: usize, k: usize) -> i128 {
        let n = nums.len();
        let mut max_sum = 0i128;

        for i in 0..(1 << n) {
            if i.count_ones() as usize != k {
                continue;
            }

            let mut segments: Vec<(usize, usize)> = Vec::new();
            let mut current_bit = 0;
            for j in 0..n {
                if (i >> j) & 1 == 1 {
                    if segments.is_empty() {
                        segments.push((j, j));
                    } else {
                        let last_segment = segments.last_mut().unwrap();
                        last_segment.1 = j;
                    }
                }
            }
            if segments.len() != k {
                continue;
            }

            let mut valid = true;
            for segment in &segments {
                if segment.0 > segment.1 {
                    valid = false;
                    break;
                }
            }
            if !valid {
                continue;
            }

            let mut num_segments = 0;
            for segment in &segments {
                num_segments += 1;
            }

            if num_segments != k {
                continue;
            }

            let mut total_sum: i128 = 0;
            for segment in &segments {
                for l in segment.0..=segment.1 {
                    total_sum += nums[l] as i128;
                }
            }

            if total_sum > max_sum {
                max_sum = total_sum;
            }
        }

        max_sum
    }
}

